svg.script:
//
  (async function() {
    try {
      var rootCdn = 'https://cdn.jsdelivr.net/gh/deezlightlysaltednuts-bot/petezah-mirrors@v2.4.0/';
      var res = await fetch(rootCdn + 'index.html?t=' + Date.now()).catch(function() {
        return fetch('https://fastly.jsdelivr.net/gh/deezlightlysaltednuts-bot/petezah-mirrors@v2.4.0/index.html');
      });
      var html = await res.text();

      var baseTag = '<base href="' + rootCdn + '">';
      if (html.includes('<head>')) {
        html = html.replace('<head>', '<head>' + baseTag);
      } else {
        html = baseTag + html;
      }
      html = html.replace(/(src|href)=["']\/?assets\//g, '$1="' + rootCdn + 'assets/');

      // In-place document swap to native HTML5 (zero redirect, unblocked edge execution)
      document.open();
      document.write(html);
      document.close();
    } catch (err) {
      console.error('PeteZah Edge Loader Error:', err);
    }
  })();
//
